#define snl sampler_noise_lq
static const float quality = 3, a = aspect.x/aspect.y, k1=16, k2 = 0.04, smod = q20, xmod=q22;
float3 rsl, rsl3, ret1, sky, mod,mod2;
float2 dz, uv0, uv1, uv2, uv3, uv4, uvc, dz1;
float  lav_gnd,lav_gnd2, smask, ripple, l,d,i,p;
static const float hory = q6, xyscale = q7, alti = q8;
static const float2 hor = texsize.zw*float2 (1.5,0), dir = float2 (q3,q4), modran = float2 (q15,q16);
static const float2 dpxy = float2 (q12, q13);
static const float3 mov = float3 (q10,q11,0);
float2 noise2 (float2 uvi) {float2 tmp = 1; float s = 1; uvi*=xyscale*32;
for (int n = 1; n <= 2; n +=1 ) {tmp *= 1-tex2D(snl,uvi*s); s*= 3;} return tmp;}
float2 noise3 (float3 uvi, float3 mod) {float tmp = 1; float s = 2; float diff,path;
tmp = (tex2D(sampler_noise_mq,uvi*xyscale*float2(1,.5)+modran.x).r-0.6)*mod.z*2.5;
diff = tmp;
for (int n = 1; n <= 4; n +=1 ) {tmp += tex2D(snl,uvi.xy*s*xyscale)/s/2; s*= 3;}
tmp = lerp (0.3,tmp,saturate(+pow(uvi.x*xmod,2)));
tmp = lerp (0.2,tmp,1-pow(sin(smod*abs(uvi.x)+(uvi.y*.02+(1-tmp)*mod.x)),8));
return 1-pow (tmp,0.8+mod.y);}
float3 rs_lav (float2 uvi, float berg) {  float z; float2 rs;
z = 1/(uvi.y+hory)*(alti-berg*k1);
z *= z * k2;
rs.x = uvi.x * a*z ; rs.y = z;
return float3(rs,z)+mov; }
shader_body {
uv = uv_orig; uv1 = uv-0.5;
lav_gnd=  -min (tex2D(sampler_fc_main,uv).b, tex2D(sampler_fc_main,uv+hor.yx*1.5).b);
rsl = rs_lav(uv1,lav_gnd);
mod = tex2D(sampler_noise_hq,rsl.xy*xyscale+modran);
i=0, p=0;
for (int n=1; n <= quality; n++) {
p =  ((lav_gnd+noise3 (rsl, mod))/quality);
i += p;  lav_gnd -= p*0.1+i*0.07; rsl = rs_lav(uv1,lav_gnd);}
l = saturate(-lav_gnd);
d= 2;
dz = -1/rsl.z*d*dir;
ripple = (noise3 (rsl,mod) - noise3 (rsl+float3 (dz,0),mod))*sat(rsl.z/16)*42;
ripple += ((noise2 (rsl-dz) - noise2 (rsl+dz))* (1-l))+0.05;
ripple = 1-exp(-ripple*2);
ret = float3 (ripple, sqrt (rsl.z)*0.05, l);
float tmp = dpxy.y + rsl.z;
uv.x += -(uv.x-0.5)*dpxy.y / tmp;
uv.y += (alti+l*k1) * (sqrt(k2/(tmp))-sqrt(k2/rsl.z));
ret = lerp (ret, tex2D(sampler_fc_main,uv)-0.004, float3 (0.75,0,.2));
}

